int main()
{
    const char *fname = "example.pi";
    FILE *f;

    // prepare input file
    f = fopen(fname, "w");
    fprintf(f,
        "//Sphere\n"
		"include \"colors.inc\"\n"
	    "object\n"
	   "{\n"
	   "sphere <0,0,5>,0.5\n"
       "shiny_red\n"
	   "}\n"
	   "\n"
	   "//Light Source\n"
	   "light <5,5,5>\n"
        "\n");
    fclose(f);

    f = fopen(fname, "rb");
    input_t in(f);
    assert(lex(in));
    fclose(f);

    // cleanup
    remove(fname);
    return 0;
}

