typedef struct lookup_table_blk *tabptr;

int
lookup(void)
{
   tabptr low  = lookup_table;
   tabptr high = END(lookup_table);
   tabptr mid;
   char *strtmp;
   int c, l1;
   void *d;
#ifdef DEBUG_FN_CALLS
message("lookup\n");
#endif

   while (low <= high) {
      mid = low + (high - low) / 2;
      if ((c = strcmp(mid->name, yytext)) == 0) {
         return mid->val;
         }
      else if (c < 0)
         low = mid + 1;
      else
         high = mid - 1;
      }

   /* If the string isn't predefined, then look for it in the symbol table */
   l1 = strlen(yytext);
   strtmp = Lookup_String(yytext);
   if (strtmp == NULL) {
      strtmp = polyray_malloc((l1+1) * sizeof(char));
      if (strtmp == NULL)
         error("Failed to allocate space for a string constant\n");
      memcpy(strtmp, yytext, l1+1);
      yylval.name = strtmp;
      return TOKEN;
      }
   else {
      Lookup_Definition(yytext, &c, &d);
      switch (c) {
      case T_OBJECT:
         yylval.name = strtmp;
         return OBJECT_SYM;
      case T_SURFACE:
         yylval.name = strtmp;
         return SURFACE_SYM;
      case T_TEXTURE:
         yylval.name = strtmp;
         return TEXTURE_SYM;
      case T_TEXTURE_MAP:
         yylval.name = strtmp;
         return TEXTURE_MAP_SYM;
      case T_TRANSFORM:
         yylval.name = strtmp;
         return TRANSFORM_SYM;
      case T_EXPRESSION:
         yylval.name = strtmp;
         return EXPRESSION_SYM;
      case T_PARTICLE:
         yylval.name = strtmp;
         return PARTICLE_SYM;
      default:
         error("Bad type in symbol table: '%s' - %d\n", yytext, c);
	 return 0; /* To remove warning about non-return value */
      } }
}

int
copy_yystring(void)
{
   int len = strlen(yytext);
   char *strtmp;
#ifdef DEBUG_FN_CALLS
message("copy_yystring\n");
#endif
   strtmp = polyray_malloc((len - 1) * sizeof(char));
   if (strtmp == NULL)
      error("Failed to allocate space for a string constant\n");
   memcpy(strtmp, &yytext[1], len-2);
   strtmp[len-2] = '\0';
   yylval.name = strtmp;
   return STRING;
}

void
ReadSceneFile(char *str)
{
#ifdef DEBUG_FN_CALLS
message("ReadSceneFile\n");
#endif
   SetInputFile(str);
   if (yyparse() == 1) //lex or scan ?
      error("Invalid input specification\n");
   //if (yyin != stdin)
   //   fclose(yyin);
}

/* Skip over comments */
static void
skipcom()
{
   int c;

   c = input();
   while (c != 0) {
      while (c == '*')
         if ((c = input()) == '/')
            return;
      c = input();
      }
   error("EOF inside comment");
}
